// standard app: sap.orders.controller.List
onSearch: function () {
  const filters = this._buildFilters();
  if (this.extHookModifyFilters) {  // documented hook
    this.extHookModifyFilters(filters);
  }
  this._table.getBinding("items").filter(filters);
}

// customer.orders.ext.controller.ListExtension, registered in the manifest under
// "sap.ui.controllerExtensions": { "sap.orders.controller.List": { "controllerName": "customer.orders.ext.controller.ListExtension" } }
sap.ui.define([
  "sap/ui/core/mvc/Controller",
  "sap/ui/model/Filter",
  "sap/ui/model/FilterOperator"
], function (Controller, Filter, FilterOperator) {
  "use strict";
  return Controller.extend("customer.orders.ext.controller.ListExtension", {
    extHookModifyFilters: function (filters) {
      filters.push(new Filter("Region", FilterOperator.EQ, "EMEA"));
    }
  });
});
